UPDATE products SET unit = '/包', description = CASE WHEN description IS NULL OR description = '' OR description = '/包' THEN '随机2种时令蔬菜，共1斤，尝鲜之选' ELSE description END WHERE name = '一斤蔬菜盲盒(2种随机)' AND (unit IS NULL OR unit = '' OR unit = '/斤' OR description = '/包');
UPDATE products SET unit = '/包', description = CASE WHEN description IS NULL OR description = '' OR description = '/包' THEN '随机3种时令蔬菜，共2斤，每天惊喜不同' ELSE description END WHERE name = '两斤蔬菜盲盒(3种随机)' AND (unit IS NULL OR unit = '' OR unit = '/斤' OR description = '/包');
UPDATE products SET unit = '/盒', description = CASE WHEN description IS NULL OR description = '' OR description = '/盒' THEN '鲜鸡蛋15枚，蛋壳干净，蛋黄饱满' ELSE description END WHERE name = '鸡蛋15枚' AND (unit IS NULL OR unit = '' OR unit = '/斤' OR description = '/盒');
UPDATE products SET unit = '/个', description = CASE WHEN description IS NULL OR description = '' OR description = '/个' THEN '金枕榴莲，果肉绵密香甜，回味悠长' ELSE description END WHERE name = '榴莲' AND (unit IS NULL OR unit = '' OR unit = '/斤' OR description = '/个');
UPDATE products SET unit = '/盒', description = CASE WHEN description IS NULL OR description = '' OR description = '/盒' THEN '新鲜桑葚，酸甜多汁，补血养颜' ELSE description END WHERE name = '[已冻结]桑葚' AND (unit IS NULL OR unit = '' OR unit = '/斤' OR description = '/盒');
